mapper.select:
select (select count(*) from spas_paper_question q join spas_paper p on p.paper_id = q.paper_id where not exists (select 1 from spas_question_knowledge qk where qk.question_id = q.question_id)
) as "noKnowledge", (select count(*) from spas_paper_question q join spas_paper p on p.paper_id = q.paper_id where nullif(trim(q.question_type), '') is null
) as "noQuestionType", (select count(*) from spas_paper_question q join spas_paper p on p.paper_id = q.paper_id where nullif(trim(q.bloom_level), '') is null
) as "noBloom", (select count(*) from ( select q.question_id from spas_paper_question q join spas_paper p on p.paper_id = q.paper_id join spas_question_knowledge qk on qk.question_id = q.question_id where 1=1
group by q.question_id having abs(coalesce(sum(qk.weight),0) - 1) > 0.0001 ) t) as "weightSum", (select count(*) from spas_student_knowledge_stat st join spas_student s on s.student_id = st.student_id where st.attempt_count < #{minAttempts} and s.del_flag = '0'
and st.subject_id = #{subjectId} ) as "lowAttempt", (select count(*) from spas_student_knowledge_stat st join spas_student s on s.student_id = st.student_id where st.attempt_count < #{minAttempts} and st.weak_level in ('1', '2', '3') and s.del_flag = '0'
and st.subject_id = #{subjectId} ) as "weakLowEvidence", (select count(*) from spas_paper p where p.exam_date is null
) as "missingExamDate", (select count(*) from ( select d.paper_id, d.student_id from spas_score_detail d join spas_paper p on p.paper_id = d.paper_id join spas_student s on s.student_id = d.student_id and s.del_flag = '0' where 1=1
group by d.paper_id, d.student_id having count(d.detail_id) < (select count(*) from spas_paper_question q where q.paper_id = d.paper_id) ) t) as "partialPaper", (select count(*) from spas_score_detail d left join spas_paper p on p.paper_id = d.paper_id join spas_student s on s.student_id = d.student_id and s.del_flag = '0' where (p.paper_id is null or p.status = '0')
and (p.subject_id = #{subjectId} or p.paper_id is null)
) as "orphanScore", (select count(*) from spas_score_detail d join spas_paper p on p.paper_id = d.paper_id join spas_student s on s.student_id = d.student_id and s.del_flag = '0' where ( d.score_source = '3' or ( coalesce(d.score_source, '2') <> '3' and d.score = 0 and exists ( select 1 from spas_score_detail d2 where d2.paper_id = d.paper_id and d2.student_id = d.student_id and d2.score > 0 ) ) )
) as "blankZero", (select count(*) from spas_score_detail d join spas_paper p on p.paper_id = d.paper_id join spas_student s on s.student_id = d.student_id and s.del_flag = '0' where 1=1
) as "scoreTotal", (select count(*) from spas_paper p where 1=1 ) as "paperCount", (select count(*) from spas_paper_question q join spas_paper p on p.paper_id = q.paper_id where 1=1 ) as "questionCount", (select count(*) from spas_paper_question q join spas_paper p on p.paper_id = q.paper_id where exists (select 1 from spas_question_knowledge qk where qk.question_id = q.question_id) ) as "boundQuestionCount", (select count(*) from ( select f.knowledge_id from ( select k.knowledge_id from spas_knowledge k join spas_question_knowledge qk on qk.knowledge_id = k.knowledge_id join spas_paper_question q on q.question_id = qk.question_id join spas_paper p on p.paper_id = q.paper_id where coalesce(k.node_type, '2') = '2'
group by k.knowledge_id having count(distinct q.question_id) >= #{questionMin} ) f join ( select st.knowledge_id from spas_student_knowledge_stat st join spas_student s on s.student_id = st.student_id and s.del_flag = '0' where 1=1
and st.subject_id = #{subjectId} group by st.knowledge_id having avg(st.weighted_rate) < #{weakRate} ) m on m.knowledge_id = f.knowledge_id ) hf) as "highFreqLowMastery"
